   243→        [MethodImpl(MethodImplOptions.NoInlining)]
   244→        private int ProcessDelegations(Transaction tx, IReleaseSpec spec, in StackAccessTracker accessTracker)
   245→        {
   246→            Debug.Assert(spec.IsEip7702Enabled && tx.HasAuthorizationList);
   247→
   248→            int refunds = 0;
   249→            foreach (AuthorizationTuple authTuple in tx.AuthorizationList)
   250→            {
   251→                Address authority = (authTuple.Authority ??= Ecdsa.RecoverAddress(authTuple));
   252→
   253→                if (!IsValidForExecution(authTuple, accessTracker, out string? error))
   254→                {
   255→                    if (Logger.IsDebug) Logger.Debug($"Delegation {authTuple} is invalid with error: {error}");
   256→                }
   257→                else
   258→                {
   259→                    if (!WorldState.AccountExists(authority))
   260→                    {
   261→                        WorldState.CreateAccount(authority, 0, 1);
   262→                    }
   263→                    else
   264→                    {
   265→                        refunds++;
   266→                        WorldState.IncrementNonce(authority);
   267→                    }
   268→
   269→                    _codeInfoRepository.SetDelegation(authTuple.CodeAddress, authority, spec);
   270→                }
   271→            }
   272→
   273→            return refunds;
   274→
   275→            bool IsValidForExecution(
   276→                AuthorizationTuple authorizationTuple,
   277→                StackAccessTracker accessTracker,
   278→                [NotNullWhen(false)] out string? error)
   279→            {
   280→                if (authorizationTuple.ChainId != 0 && SpecProvider.ChainId != authorizationTuple.ChainId)
   281→                {
   282→                    error = $"Chain id ({authorizationTuple.ChainId}) does not match.";
   283→                    return false;
   284→                }
   285→
   286→                if (authorizationTuple.Nonce == ulong.MaxValue)
   287→                {
   288→                    error = $"Nonce ({authorizationTuple.Nonce}) must be less than 2**64 - 1.";
   289→                    return false;
   290→                }
   291→
   292→                UInt256 s = new(authorizationTuple.AuthoritySignature.SAsSpan, isBigEndian: true);
   293→                if (authorizationTuple.Authority is null
   294→                    || s > Secp256K1Curve.HalfN
   295→                    //V minus the offset can only be 1 or 0 since eip-155 does not apply to Setcode signatures
   296→                    || authorizationTuple.AuthoritySignature.V - Signature.VOffset > 1)
   297→                {
   298→                    error = "Bad signature.";
   299→                    return false;
   300→                }
   301→
   302→                accessTracker.WarmUp(authorizationTuple.Authority);
   303→
   304→                if (WorldState.HasCode(authorizationTuple.Authority) && !_codeInfoRepository.TryGetDelegation(authorizationTuple.Authority, spec, out _))
   305→                {
   306→                    error = $"Authority ({authorizationTuple.Authority}) has code deployed.";
   307→                    return false;
   308→                }
   309→
   310→                UInt256 authNonce = WorldState.GetNonce(authorizationTuple.Authority);
   311→                if (authNonce != authorizationTuple.Nonce)
   312→                {
   313→                    error = $"Skipping tuple in authorization_list because nonce is set to {authorizationTuple.Nonce}, but authority ({authorizationTuple.Authority}) has {authNonce}.";
   314→                    return false;
   315→                }
   316→
   317→                error = null;
   318→                return true;
   319→            }
   320→        }
