   455→        protected virtual TransactionResult ValidateSender(Transaction tx, BlockHeader header, IReleaseSpec spec, ITxTracer tracer, ExecutionOptions opts)
   456→        {
   457→            bool validate = !opts.HasFlag(ExecutionOptions.SkipValidation);
   458→
   459→            if (validate && WorldState.IsInvalidContractSender(spec, tx.SenderAddress!))
   460→            {
   461→                TraceLogInvalidTx(tx, "SENDER_IS_CONTRACT");
   462→                return TransactionResult.SenderHasDeployedCode;
   463→            }
   464→
   465→            return TransactionResult.Ok;
