   468→        protected virtual TransactionResult BuyGas(Transaction tx, IReleaseSpec spec, ITxTracer tracer, ExecutionOptions opts,
   469→                in UInt256 effectiveGasPrice, out UInt256 premiumPerGas, out UInt256 senderReservedGasPayment, out UInt256 blobBaseFee)
   470→        {
   471→            premiumPerGas = UInt256.Zero;
   472→            senderReservedGasPayment = UInt256.Zero;
   473→            blobBaseFee = UInt256.Zero;
   474→            bool validate = !opts.HasFlag(ExecutionOptions.SkipValidation);
   475→
   476→            if (validate)
   477→            {
   478→                BlockHeader header = VirtualMachine.BlockExecutionContext.Header;
   479→                if (!TryCalculatePremiumPerGas(tx, header.BaseFeePerGas, out premiumPerGas))
   480→                {
   481→                    TraceLogInvalidTx(tx, "MINER_PREMIUM_IS_NEGATIVE");
   482→                    return TransactionResult.MinerPremiumNegative;
   483→                }
   484→
   485→                UInt256 senderBalance = WorldState.GetBalance(tx.SenderAddress!);
   486→                if (UInt256.SubtractUnderflow(in senderBalance, in tx.ValueRef, out UInt256 balanceLeft))
   487→                {
   488→                    TraceLogInvalidTx(tx, $"INSUFFICIENT_SENDER_BALANCE: ({tx.SenderAddress})_BALANCE = {senderBalance}");
   489→                    return TransactionResult.InsufficientSenderBalance;
   490→                }
   491→
   492→                bool overflows;
   493→                if (spec.IsEip1559Enabled && !tx.IsFree())
   494→                {
   495→                    overflows = UInt256.MultiplyOverflow((UInt256)tx.GasLimit, tx.MaxFeePerGas, out UInt256 maxGasFee);
   496→                    if (overflows || balanceLeft < maxGasFee)
   497→                    {
   498→                        TraceLogInvalidTx(tx, $"INSUFFICIENT_MAX_FEE_PER_GAS_FOR_SENDER_BALANCE: ({tx.SenderAddress})_BALANCE = {senderBalance}, MAX_FEE_PER_GAS: {tx.MaxFeePerGas}");
   499→                        return TransactionResult.InsufficientMaxFeePerGasForSenderBalance;
   500→                    }
   501→
   502→                    if (tx.SupportsBlobs)
   503→                    {
   504→                        overflows = UInt256.MultiplyOverflow(BlobGasCalculator.CalculateBlobGas(tx), (UInt256)tx.MaxFeePerBlobGas!, out UInt256 maxBlobGasFee);
   505→                        if (overflows || UInt256.AddOverflow(maxGasFee, maxBlobGasFee, out UInt256 multidimGasFee) || multidimGasFee > balanceLeft)
   506→                        {
   507→                            TraceLogInvalidTx(tx, $"INSUFFICIENT_MAX_FEE_PER_BLOB_GAS_FOR_SENDER_BALANCE: ({tx.SenderAddress})_BALANCE = {senderBalance}");
   508→                            return TransactionResult.InsufficientSenderBalance;
   509→                        }
   510→                    }
   511→                }
   512→
   513→                overflows = UInt256.MultiplyOverflow((UInt256)tx.GasLimit, effectiveGasPrice, out senderReservedGasPayment);
   514→                if (!overflows && tx.SupportsBlobs)
   515→                {
   516→                    overflows = !BlobGasCalculator.TryCalculateBlobBaseFee(header, tx, spec.BlobBaseFeeUpdateFraction, out blobBaseFee);
   517→                    if (!overflows)
   518→                    {
   519→                        overflows = UInt256.AddOverflow(senderReservedGasPayment, blobBaseFee, out senderReservedGasPayment);
   520→                    }
   521→                }
   522→
   523→                if (overflows || senderReservedGasPayment > balanceLeft)
   524→                {
   525→                    TraceLogInvalidTx(tx, $"INSUFFICIENT_SENDER_BALANCE: ({tx.SenderAddress})_BALANCE = {senderBalance}");
   526→                    return TransactionResult.InsufficientSenderBalance;
   527→                }
   528→            }
   529→
   530→            if (validate) WorldState.SubtractFromBalance(tx.SenderAddress, senderReservedGasPayment, spec);
   531→
   532→            return TransactionResult.Ok;
   533→        }
