   552→        [SkipLocalsInit]
   553→        private TransactionResult BuildExecutionEnvironment(
   554→            Transaction tx,
   555→            IReleaseSpec spec,
   556→            ICodeInfoRepository codeInfoRepository,
   557→            in StackAccessTracker accessTracker,
   558→            out ExecutionEnvironment env)
   559→        {
   560→            Address recipient = tx.GetRecipient(tx.IsContractCreation ? WorldState.GetNonce(tx.SenderAddress!) : 0);
   561→            if (recipient is null) ThrowInvalidDataException("Recipient has not been resolved properly before tx execution");
   562→
   563→            ICodeInfo? codeInfo;
   564→            ReadOnlyMemory<byte> inputData = tx.IsMessageCall ? tx.Data : default;
   565→            if (tx.IsContractCreation)
   566→            {
   567→                if (CodeInfoFactory.CreateInitCodeInfo(tx.Data, spec, out codeInfo, out ReadOnlyMemory<byte> trailingData))
   568→                {
   569→                    inputData = trailingData;
   570→                }
   571→            }
   572→            else
   573→            {
   574→                codeInfo = codeInfoRepository.GetCachedCodeInfo(recipient, spec, out Address? delegationAddress);
   575→
   576→                //We assume eip-7702 must be active if it is a delegation
   577→                if (delegationAddress is not null)
   578→                    accessTracker.WarmUp(delegationAddress);
   579→            }
   580→
   581→            if (spec.UseHotAndColdStorage)
   582→            {
   583→                if (spec.UseTxAccessLists)
   584→                    accessTracker.WarmUp(tx.AccessList); // eip-2930
   585→
   586→                if (spec.AddCoinbaseToTxAccessList)
   587→                    accessTracker.WarmUp(VirtualMachine.BlockExecutionContext.Header.GasBeneficiary!);
   588→
   589→                accessTracker.WarmUp(recipient);
   590→                accessTracker.WarmUp(tx.SenderAddress!);
   591→            }
   592→
   593→            env = new ExecutionEnvironment(
   594→                codeInfo: codeInfo,
   595→                executingAccount: recipient,
   596→                caller: tx.SenderAddress,
   597→                codeSource: recipient,
   598→                callDepth: 0,
   599→                transferValue: in tx.ValueRef,
   600→                value: in tx.ValueRef,
   601→                inputData: in inputData);
   602→
   603→            return TransactionResult.Ok;
   604→        }
