   508→            .PushData(TestItem.AddressA)
   509→            .Op(Instruction.EXTCODESIZE)
   510→            .Op(Instruction.PUSH0)
   511→            .Op(Instruction.MSTORE8)
   512→            .PushData(1)
   513→            .Op(Instruction.PUSH0)
   514→            .Op(Instruction.RETURN)
   515→            .Done,
   516→            new byte[]{ (byte)Eip7702Constants.DelegationDesignatorLength } };
   517→        byte[] delegationCode = [.. Eip7702Constants.DelegationHeader, .. TestItem.AddressC.Bytes];
