   524→            .Op(Instruction.MSTORE)
   525→            .PushData(32)
   526→            .Op(Instruction.PUSH0)
   527→            .Op(Instruction.RETURN)
   528→            .Done,
   529→            Keccak.Compute(delegationCode).Bytes.ToArray() };
   530→        //EXTCOPYCODE should copy the the delegation designator
   531→        byte[] code = Prepare.EvmCode
   532→            .PushData(TestItem.AddressA)
