   537→            .Op(Instruction.DUP4)
   538→            .Op(Instruction.EXTCODECOPY)
   539→            .PushData(23)
   540→            .Op(Instruction.PUSH0)
   541→            .Op(Instruction.RETURN)
   542→            .Done;
   543→        yield return new object[]
   544→        {
   545→            code,
   546→            delegationCode
   547→        };
